def find_frames(grid):
    """Every complete rectangular frame (border of one color) as (color, top, left, bottom, right)."""
    frames=[]
    for c in {v for row in grid for v in row if v}:
        cells=[(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v==c]
        if len(cells)<8: continue
        rs=[i for i,_ in cells]; cs=[j for _,j in cells]
        t_,b,l,r_=min(rs),max(rs),min(cs),max(cs)
        if b-t_>=2 and r_-l>=2 and all(grid[i][j]==c for i in range(t_,b+1) for j in (l,r_)) and all(grid[t_][j]==c and grid[b][j]==c for j in range(l,r_+1)):
            frames.append((c,t_,l,b,r_))
    return frames

def checkerboard_interior(grid, frame, color):
    """Fill the inside of frame with color in a checkerboard pattern starting colored at the top-left interior cell."""
    c,t_,l,b,r_=frame
    g=[row[:] for row in grid]
    for i in range(t_+1,b):
        for j in range(l+1,r_):
            if (i+j)%2==0: g[i][j]=color
    return g

def remove_colors(grid, colors):
    """Every cell whose color is in colors becomes 0."""
    return [[0 if v in colors else v for v in row] for row in grid]

